return {{date="2026-10-28",author="CrazySpottedDove",message="refactor(破坏性): 进一步将英雄数据注册和UI解耦合，不再维护HERO的SPECIAL文本，直接通过各个SKILL拼接。SKILL的i18n key改为在init.lua中注册，而非挂在英雄的模板上"},{date="2026-10-28",author="CrazySpottedDove",message="perf(可能破坏部分资源管理极其糟糕的插件): image_db添加批量卸载接口，优化开启大量插件或英雄菜单情况下的退出对局耗时"},{date="2026-10-28",author="CrazySpottedDove",message="refactor: 使一代英雄通过registry注册，相关模板只在携带时进入数据库"},{date="2026-10-28",author="CrazySpottedDove",message="fix: 修复英雄殿堂多次点击英雄头像时文本跳动的问题"},{date="2026-10-28",author="CrazySpottedDove",message="fix: 修复插件管理器输入文字后，关闭插件管理器，焦点不解除导致快捷键失效的问题"},{date="2026-10-28",author="CrazySpottedDove",message="refactor: 使二代英雄通过registry注册"},{date="2026-10-28",author="CrazySpottedDove",message="fix: 修复老兵模式下tsv出怪后期节奏异常紧凑的问题"},{date="2026-10-29",author="CrazySpottedDove",message="refactor: 将剩余的英雄改为通过registry注册"},{date="2026-10-29",author="CrazySpottedDove",message="fix: 优化奥术幻铸师的技能释放逻辑，并修复其吞技能的问题"},{date="2026-10-29",author="CrazySpottedDove",message="doc: 修改更新插件需要更高的版本号时的提示文本"},{date="2026-10-29",author="CrazySpottedDove",message="chore: 添加windows开发包构建选项"},{date="2026-10-29",author="CrazySpottedDove",message="chore: 安卓端改为普清/高清/超清打包选项"},{date="2026-10-29",author="CrazySpottedDove",message="feat: 添加6代英雄的UI资源，并试移植杰拉尔德"},{date="2026-10-29",author="CrazySpottedDove",message="fix: 使英雄菜单按钮自适应图片大小"},{date="2026-10-29",author="CrazySpottedDove",message="refactor: 清除hero registry中无效的portrait, thumb, icon字段"},{date="2026-10-29",author="CrazySpottedDove",message="refactor: 清除hero registry中无效的from_kr字段"},{date="2026-10-29",author="CrazySpottedDove",message="refactor: 清除hero registry中无效的starting_level字段"},{date="2026-10-29",author="CrazySpottedDove",message="feat: 新增英雄：泽菲拉"},{date="2026-10-29",author="CrazySpottedDove",message="balance: 下放泽菲拉传送至一级"},{date="2026-10-29",author="CrazySpottedDove",message="balance: 提高精灵精英游侠1点伤害下限"},{date="2026-10-29",author="CrazySpottedDove",message="balance: 调整精灵精英游侠的技能价格，并减少其2技能的真空期与持续时间"},{date="2026-10-29",author="CrazySpottedDove",message="balance: 加快矿工回本，减少矿工后期收益"},{date="2026-10-29",author="CrazySpottedDove",message="fix: 修复部分英雄的偏移"},{date="2026-10-29",author="CrazySpottedDove",message="balance: 加快6代杰拉尔德和泽菲拉的升级速度"},{date="2026-10-29",author="CrazySpottedDove",message="balance: 加强泽菲拉的大招效果"},{date="2026-10-30",author="CrazySpottedDove",message="balance: 优化六代爵士操作手感，使其技能后摇可以手操打断；替换六代爵士普攻造成真实伤害；修正牢铁代码导致的鼓舞只对少部分士兵生效的问题"},{date="2026-10-30",author="CrazySpottedDove",message="balance: 使泽菲拉释放大招的后摇可以打断"},{date="2026-10-30",author="CrazySpottedDove",message="balance: 提升泽菲拉技能和近战普攻的经验获取量"},{date="2026-10-30",author="CrazySpottedDove",message="perf: 优化局内英雄菜单的打开性能"}}
